    starter: `${READ}\nconst nums = tokens.map(Number);\nconst P = nums.length ? nums[0] : 0;\nconst ids = nums.slice(1);\nconst canary = [];\n// TODO: bucket each id with (id * 37) % 100 < P.\nconsole.log('canary=' + canary.length + ' stable=' + (ids.length - canary.length) + ' ids=' + canary.join(' '));`,
    solution: `${READ}\nconst nums = tokens.map(Number);\nconst P = nums.length ? nums[0] : 0;\nconst ids = nums.slice(1);\nconst canary = ids.filter((id) => (id * 37) % 100 < P);\nconsole.log('canary=' + canary.length + ' stable=' + (ids.length - canary.length) + ' ids=' + canary.join(' '));`,
