    solution: `${READ}\nconst seen = new Set();\nconst results = [];\nlet origin = 0;\nfor (let i = 0; i + 1 < tokens.length; i += 2) {\n  const key = tokens[i] + ':' + tokens[i + 1];\n  if (seen.has(key)) results.push('HIT');\n  else { seen.add(key); results.push('MISS'); origin += 1; }\n}\nconsole.log('results=' + results.join(' ') + ' origin=' + origin);`,
