    solution: `${READ}\nconst nums = tokens.map(Number);\nconst out = [];\nfor (let i = 0; i + 3 < nums.length; i += 4) {\n  const N = nums[i], W = nums[i + 1], R = nums[i + 2], UP = nums[i + 3];\n  const yn = (b) => (b ? 'YES' : 'NO');\n  out.push('write=' + yn(UP >= W) + ' read=' + yn(UP >= R) + ' strong=' + yn(R + W > N));\n}\nconsole.log(out.join(' ; '));`,
